-- FR-BILL-4: a verified payment can be closed with no invoice owed, with a reason, and the activity
-- log names it. The CHECKs are added over tables with rows, which Postgres validates with a query:
-- system context (mistake 20).
SELECT set_config('app.rls_system', 'on', true);--> statement-breakpoint
ALTER TABLE "audit_events" DROP CONSTRAINT "audit_events_action_check";--> statement-breakpoint
ALTER TABLE "payments" ADD COLUMN "invoice_waived_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "payments" ADD COLUMN "invoice_waived_reason" text;--> statement-breakpoint
ALTER TABLE "audit_events" ADD CONSTRAINT "audit_events_action_check" CHECK (action IN ('organization.created', 'organization.went_live', 'organization.two_factor_requirement_changed', 'organization.settings_changed', 'branch.created', 'branch.updated', 'issue_point.created', 'issue_point.document_types_changed', 'issue_point.paused_changed', 'sequence.starting_set', 'certificate.uploaded', 'member.invited', 'member.invitation_revoked', 'member.joined', 'member.role_changed', 'member.removed', 'member.issue_points_changed', 'agreements.accepted', 'session.started', 'subscription.plan_changed', 'subscription.billing_changed', 'subscription.price_changed', 'subscription.module_added', 'subscription.module_removed', 'subscription.limit_set', 'subscription.limit_cleared', 'entitlements.override_set', 'entitlements.override_cleared', 'payment.created', 'payment.reported', 'payment.cancelled', 'payment.verified', 'payment.rejected', 'payment.refunded', 'subscription.change_scheduled', 'subscription.cancelled', 'subscription.resumed', 'organization.suspended', 'organization.reactivated', 'subscription.renewal_due', 'subscription.grace_started', 'subscription.past_due', 'subscription.moved_to_free', 'payment.card_duplicate', 'payment.invoiced', 'payment.invoice_waived', 'payment.card_resolved', 'payment.repriced', 'subscription.custom_billing_started', 'subscription.moved_to_custom', 'subscription.module_complimentary'));--> statement-breakpoint
ALTER TABLE "payments" ADD CONSTRAINT "payments_invoice_waived_check" CHECK ((invoice_waived_at IS NULL) = (invoice_waived_reason IS NULL) AND (invoice_waived_at IS NULL OR invoiced_at IS NULL));
--> statement-breakpoint
SELECT set_config('app.rls_system', '', true);
